"""Integrate the reviewed external T-cell result into the working draft."""
from pathlib import Path
import json,shutil,hashlib
import numpy as np,pandas as pd
R=Path(__file__).resolve().parent;B=R.parent;W=B/'conference_manuscript_20261027'

def read(p):return json.loads(Path(p).read_text(encoding='utf-8-sig'))
def augment_paper(paper,bib,keys,text,heading,table,figure,page):
 assert read(R/'results/postrun_audit.json')['state']=='passed'
 result=read(R/'results/summary.json');coverage=read(R/'results/coverage.json');prov=read(R/'prepared/count_provenance.json')
 per=pd.read_csv(R/'results/per_condition_scores.csv');positive=pd.read_csv(R/'results/guide_disjoint_positive_controls.csv');aligned=pd.read_csv(R/'results/aligned_ensemble_controls.csv');negative=pd.read_csv(R/'results/wrong_target_controls.csv')
 # All results and all source seeds are retained separately from old estimands.
 for n in ['coverage.json','summary.json','all_model_rows.csv','per_condition_scores.csv','per_seed_condition_scores.csv','guide_disjoint_positive_controls.csv','wrong_target_controls.csv','aligned_ensemble_controls.csv','paired_target_contrasts.json','source_additive_selection.json','postrun_audit.json']:
  shutil.copy2(R/'results'/n,W/('PrimaryT_'+n))
 for n in ['protocol_frozen.json','FREEZE_LOCK.json','transfer_verification.json']:
  shutil.copy2(R/n,W/('PrimaryT_'+n))
 shutil.copy2(R/'prepared/count_provenance.json',W/'PrimaryT_count_provenance.json')
 bib['arce']={'doi':'10.1038/s41586-024-08314-y','title':'Central control of dynamic gene circuits governs T cell rest and activation','authors':['Maya M. Arce','Jennifer M. Umhoefer','Nadia Arang','Sivakanthan Kasinathan','Jacob W. Freimer','Zachary Steinhart','Haolin Shen','Minh T. N. Pham','Mineto Ota','Anika Wadhera','Rama Dajani','Dmytro Dorovskyi','Yan Yi Chen','Qi Liu','Yuan Zhou','Danielle L. Swaney','Kirsten Obernier','Brian R. Shy','Julia Carnevale','Ansuman T. Satpathy','Nevan J. Krogan','Jonathan K. Pritchard','Alexander Marson'],'venue':['Nature'],'published':{'date-parts':[[2025]]},'type':'journal-article','online_date':'2024-12-11','publisher_url':'https://www.nature.com/articles/s41586-024-08314-y'}
 keys.append('arce')
 refpage=next(pg for pg in paper if pg[0].get('text')=='References')
 refpage.append(text('[10] Maya M. Arce, Jennifer M. Umhoefer, Nadia Arang, et al. Central control of dynamic gene circuits governs T cell rest and activation. Nature 637, 930-939 (2025); published online 11 December 2024. DOI: 10.1038/s41586-024-08314-y.'))
 abstract=('We evaluate FVcell, a shared-response and context-residual predictor, to distinguish gains from response evidence from gains in architecture. Frozen evidence permissions, strong simple baselines and four donor holdouts are followed by two externally sourced studies. The source analyses contain 33,258 pooled target-condition responses and 129,671 donor-resolved aggregates. On pooled held-out combinations, FVcell has mean absolute error (MAE) 0.173411, versus 0.173536 for concatenation and 0.172030 for shrunk additive prediction. Learned hierarchical shrinkage adds no material four-donor benefit over fixed shrinkage or equally continued optimization. In a separate K562/RPE1 study with 519 targets and 6,795 shared genes, FVcell MAE is 0.232618 versus 0.227809 for zero response. In a further same-modality primary-T experiment, 122,538 quality-controlled cells yield 28 targets across resting and stimulated effector and regulatory T cells, with 18,103 shared genes. On the prespecified effector backgrounds, the frozen hierarchical model has MAE 0.130631 versus 0.113051 for zero response and 0.126337 for source-only additive prediction. Its target retrieval is 4.17%, near the 3.57% tied-random reference, while source target lookup reaches 42.86% despite larger MAE. Guide-disjoint agreement is modest and the external donors were pooled, preventing donor-disjoint confirmation. All backgrounds and source seeds are retained. These results expose limits of this implementation and demonstrate why aggregate error, evidence access and intervention identity must be assessed together; they do not establish algorithmic superiority or clinical validity.')
 paper[0][4]=text(abstract)
 paper[0][-1]=text('We ask whether supporting response evidence can be separated from architectural gains; whether learned hierarchical pooling improves on fixed shrinkage and matched optimization; and whether within-study error transfers to separately sourced experiments. The answers are qualified: evidence permissions change the task, hierarchical improvements are negligible, and neither the cell-line nor the same-modality primary-T test supports robust intervention-specific transfer.')
 source_table=next(b for b in paper[1] if b['kind']=='table')
 source_table['rows'].append(['External primary T','Pooled-donor target x subtype/culture','18,103 shared','Study; no donor proof'])
 # Amend limitations without replacing earlier unfavorable results.
 discussion=paper[7]
 discussion[0]=heading('7.4  Cell-line measurement and negative controls')
 discussion[5]=text('Our evidence does not support superiority over the strongest simple pooled baseline, a meaningful learned-hierarchy advantage, robust functional validation, or reliable cross-study transfer. This conclusion is specific to the implementation, processed resources and metrics tested. Only four source individuals are available. External studies change assay or cell composition; the new primary-T donors were pooled and their identities cannot be proven disjoint. Retained-gene universes differ, and some test summaries were known before exploratory extensions. These are not claims about every virtual-cell model. The full pipelines of the nearest preprints [6-8] were not reproduced, so parity or superiority to those systems is not established.')
 discussion[6]=text('Methodological novelty is limited by direct prior work on response decomposition, transportability and evidence conditioning [6-8]. We present an auditable case study, not proof that these components are new. A stronger computational-methods submission requires a clearly distinct technical contribution with supporting evidence. More training cannot itself create that contribution. Same-modality external data now provide an additional test, but do not remove the subtype, guide, culture and pooled-donor limitations.')
 discussion[-1]=text('GSE278572 is now evaluated from complete counts under the frozen protocol described above. The closer genome-scale CD4 resource at Zenodo 18876252 remains embargoed and contributes no labels. No public code release or conference submission has been performed.')
 names=[('zero','Zero response'),('source_training_mean','Training mean'),('source_shrunk_additive','Shrunk additive'),('source_same_target_mean','Target mean'),('source_ridge_P1','Ridge P1'),('concat_original_P1','Concat P1'),('fv_continued','Continued FV'),('fixed_gaussian','Fixed Gaussian'),('hierarchical','Hierarchy')]
 rows=[[name,f'{result[fam]["Teff"]["mae"]:.6f}',f'{result[fam]["Treg"]["mae"]:.6f}',('n/a' if result[fam]['Teff']['pearson'] is None else f'{result[fam]["Teff"]["pearson"]:.4f}'),f'{100*result[fam]["Teff"]["retrieval_top1"]:.2f}'] for fam,name in names]
 p1=page(heading('7.2  Same-modality primary-T transfer'),text('We additionally evaluate Arce et al. [10], GSE278572, using the complete public integer count matrix, not a significant-gene table. Its Perturb-CITE-seq uses Zim3-dCas9 CRISPRi. Both resting and 48-hour stimulated Teff are prespecified primary backgrounds; both Treg backgrounds are secondary. Two donors were pooled before sequencing. The study is a separate experiment with overlapping laboratories; donor identities cannot be verified disjoint from the source cohort. This is neither independent-laboratory validation nor proof of new-person transfer.'),text('Of 249,799 input barcodes, 140,641 have one guide and 122,538 pass frozen library, gene-count, mitochondrial and hashtag QC. All 28 uniquely mapped targets pass count-only eligibility in all four backgrounds, yielding 112 aggregates across 18,103 shared genes. Library denominators include all 36,601 RNA features. The 26 absent source input features are imputed using source training-donor controls; missing output genes are masked. External NTCs are permitted inputs, while external perturbation responses never enter fitting or model selection.'),table(['Source model','Teff MAE','Treg MAE','Teff r','Teff top-1 %'],rows,[132,84,84,84,84],'Table 6. Equal means over the two prespecified backgrounds per subtype. Neural scores average all three frozen source seeds (11, 29, 47); source fold 0 was fixed in advance. The target panel has 28 candidates per background.'),text('Hierarchy exceeds zero-response Teff MAE by 0.017580 (descriptive target-bootstrap 95% interval [0.016693, 0.018564]) and source-only additive prediction by 0.004294. It is nearly indistinguishable from fixed shrinkage and slightly worse than equally continued FV. These paired intervals describe this selected 28-target panel, not a donor population. All four conditions and every seed are retained in PrimaryT_per_seed_condition_scores.csv.'))
 # A compact figure retains all four backgrounds, including secondary Treg.
 import matplotlib.pyplot as plt
 fig,axs=plt.subplots(1,2,figsize=(6.5,2.05));tags=['Resting_Teff','Stimulated_Teff','Resting_Treg','Stimulated_Treg'];labels=['Rest Teff','48h Teff','Rest Treg','48h Treg'];x=np.arange(4)
 for fam,lab,color,shift in [('zero','Zero','#999999',-.23),('hierarchical','Hierarchy','#23618c',0),('source_same_target_mean','Target mean','#2e7d63',.23)]:
  q=per[per.model.eq(fam)].set_index('condition').loc[tags];axs[0].bar(x+shift,q.mae,width=.22,label=lab,color=color);axs[1].bar(x+shift,q.retrieval_top1*100,width=.22,color=color)
 axs[0].set_ylabel('MAE');axs[1].set_ylabel('Top-1 retrieval (%)');axs[1].axhline(100/28,ls='--',color='#555555',lw=.8)
 for ax in axs:ax.set_xticks(x,labels,rotation=20,fontsize=10)
 fig.legend(loc='upper center',ncol=3,frameon=False,fontsize=10,bbox_to_anchor=(.53,1.04));fig.tight_layout(rect=[0,0,1,.88]);f=W/'figures/primary_t_transfer.png';fig.savefig(f);plt.close(fig)
 qrows=[]
 for tag,label in zip(tags,labels):
  q=per[per.condition.eq(tag)].set_index('model');pp=positive[positive.condition.eq(tag)]
  qrows.append([label,f'{q.loc["hierarchical","mae"]:.6f}',f'{q.loc["zero","mae"]:.6f}',f'{pp.pearson.mean():.4f}',str(len(pp))])
 p2=page(heading('7.3  Primary-T identity and measurement controls'),figure(f,'Figure 4. All prespecified backgrounds are shown. Neural bars average seed-specific metrics. The dashed line denotes tied-random retrieval (3.57%); target lookup transfers identity with worse amplitude/error.'),table(['Background','Hierarchy MAE','Zero MAE','Guide r','Guide pairs'],qrows,[112,94,90,82,90],'Table 7. Disjoint guides and disjoint NTC subsets cover all 28 targets per background, with at least 25 target cells and 100 NTC cells in each half.'),text('The hierarchical model has low signed association and truth-aligned amplitude (Teff means 0.0252 and 0.0123). Target lookup has larger Teff association (0.1335), amplitude (0.1738) and top-1 retrieval (42.86%), although worse MAE (0.185888). This reproduces the error-versus-identity tension observed in the cell-line study. It does not show that the lookup is an adequately calibrated response predictor.'),text('Guide-disjoint agreement ranges from 0.1416 to 0.3289 across the four backgrounds. Guides have different efficacy and NTC halves contain different cells; this is a measurement check, not independent donors or a universal noise ceiling. Matched and wrong-target predictions are compared on the same seed-mean ensemble (Appendix C). Twenty fixed derangements largely erase target-lookup identity; hierarchy remains near chance. No condition is selected for favorable performance.'),text('This extension was frozen before full count outcomes, but an earlier significance-only panel from the same publication had been inspected. It is therefore an exploratory external test, not pristine prospective confirmation. The target panel itself was selected by the source experimental study. It cannot establish genome-wide or globally unseen-target transfer.'))
 paper=paper[:7]+[p1,p2]+paper[7:]
 crows=[]
 for fam,name in [('hierarchical','Hierarchy'),('source_same_target_mean','Target mean')]:
  for tag,label in zip(tags,labels):
   a=aligned[aligned.model.eq(fam)&aligned.condition.eq(tag)].iloc[0];n=negative[negative.model.eq(fam)&negative.condition.eq(tag)]
   crows.append([name,label,f'{a.mae:.6f}',f'{n.mae.mean():.6f}',f'{100*a.retrieval_top1:.2f}',f'{100*n.retrieval_top1.mean():.2f}'])
 cells=pd.read_csv(R/'prepared/evaluation_rows.csv').groupby('condition').agg(targets=('target','nunique'),min_cells=('n_cells','min'),ntc=('n_control_cells','first'))
 paper.append(page(heading('Appendix C  Complete primary-T transfer audit'),table(['Ensemble','Background','Matched MAE','Wrong MAE','Matched top-1 %','Wrong top-1 %'],crows,[83,85,75,75,75,75],'Table S3. Matched and deranged predictions use identical ensembles. Wrong-target scores average 20 fixed derangements; they are not compared with seed-averaged main scores.'),text('Frozen QC requires one assigned guide, at least 1,000 RNA UMIs and 500 detected RNA features, mitochondrial fraction at most 0.20, largest hashtag count at least 50 and largest/runner-up ratio at least 3. All 28 targets pass the 50-cell aggregate threshold in all four backgrounds; matched NTC counts are 4,325 (Rest Teff), 4,439 (48h Teff), 4,292 (Rest Treg) and 5,724 (48h Treg). The minimum target counts in these backgrounds are 193, 354, 133 and 446.'),text('The count stream contains 36,807 features, 249,799 barcodes and 1,027,798,128 entries. Two complete streams verify the gzip CRC and entry count. All 1,840 received chunks were re-read and matched their recorded SHA256 values; no independent publisher checksum is available. The full local SHA256 is 344a890a56a93bb01c4f7d86bd55ecca118950af43e20023e84c9a689cbb00d5. All 112 gold rows and NTC inputs were reconstructed from guide counts in a post-run audit.'),text('PrimaryT_protocol_frozen.json, PrimaryT_FREEZE_LOCK.json and PrimaryT_postrun_audit.json retain permissions and checks. PrimaryT_per_condition_scores.csv and PrimaryT_per_seed_condition_scores.csv report all backgrounds and seeds; PrimaryT_all_model_rows.csv retains every target score. All 17 frozen source files pass hash verification. A 4 x 4 additive grid uses only original source validation; no external outcome selects its weights. Full source method-task results remain in Supplementary_All_Model_Results.csv.'),text('Positive-control files include computational singleton retrieval values equal to one because each guide pair was assessed alone. Those values are not valid panel retrieval estimates and are not reported as biological identity accuracy. Only signed-response agreement, error, amplitude and direction from these pairwise checks are interpreted.')))
 return paper

def companion_pages(page,text,heading,table):
 return [page({'kind':'title','text':'独立研究验证与会议稿更新说明'},text('2026-10-27 | 两项外部研究均已评估，保留全部负结果'),heading('原代 T 细胞验证已经完成'),text('GSE278572 的完整计数文件已下载并通过分块 SHA256、完整文件哈希、两次完整解压读取的 gzip CRC 和矩阵记录数检查。249,799 个条形码中，122,538 个单 guide 细胞通过预先冻结的质量标准。最终覆盖 28 个靶点、静息与刺激后 48 小时的 Teff/Treg 四种背景，以及 18,103 个共有输出基因，共 112 条真实聚合响应。'),text('外部实验采用 CRISPRi。评估使用已有冻结权重，不以外部响应训练、微调或选择超参数；全部预定背景、三个源训练种子和九类模型/基线均保留。26 个缺失输入基因用源训练供者的对照均值补齐，缺失输出只作掩码；没有用预测填写真值。'),table(['模型','主要 Teff 误差','次要 Treg 误差'],[['零响应','0.113051','0.122384'],['源训练均值','0.126238','0.136417'],['源收缩加性基线','0.126337','0.136353'],['继续优化 FV','0.130620','0.140575'],['层级模型','0.130631','0.140576'],['源同靶点均值','0.185888','0.194447']],[204,132,132]),text('最直白的结论：目前模型对新实验的预测，还不如先假设“细胞没有变化”来得准确。层级模型在主要 Teff 背景的靶点识别率为 4.17%，接近随机参照 3.57%；直接搬用源数据的同靶点均值能识别 42.86%，但表达变化幅度和平均误差更差。因此，平均误差和是否认出具体扰动，必须同时看。'),heading('这项验证能证明什么'),text('这是另一项研究、另一次实验的原代 T 细胞测试，但相关实验室有重合。两名供者在测序前已混合，不能证明与 GWT 供者身份完全不重合，不能称为“独立供者”或“独立实验室”验证。Teff/Treg 亚型、培养和平台也存在差异。四种背景的 guide 分离相关性为 0.142 至 0.329，不等于供者重复或全体噪声上限。此前看过同论文的小型显著基因表，因此本次完整响应测试仍标为探索性扩展。')),
 page(heading('此前的外部负结果继续保留'),text('Replogle 2022 的 K562/RPE1 复核覆盖 519 个靶点、6,795 个共有基因和 1,038 条响应。FVcell 误差为 0.232618，零响应为 0.227809；同靶点均值的平均误差更差，但扰动识别更好。只有 63 个靶点-背景对满足 guide 分离检查，相关性很弱，不能当全体面板的噪声上限。本次没有用原代 T 数据替换或隐藏这项失败。'),heading('稿件已经更新，科学缺口仍然存在'),text('英文主文扩展为 10 页，另附参考文献和附录；新增原代 T 细胞方法、结果、完整性证据、四背景图表和全部种子附表，并同步修改摘要、讨论和限制。可编辑 Markdown、LaTeX 源、结果表和审计记录一并更新。交付 PDF 用 ReportLab 生成并逐页渲染检查；内置 LaTeX 编译仍受 Windows 沙箱限制，未宣称 TeX 编译成功。'),text('当前结果不支持“模型领先”“分层显著增益”“广泛泛化”“器官模拟”或“临床有效”。最近邻工作已经提出共享响应、背景残差、跨供者和证据条件化设计。RECOMB 稿件仍缺清楚且独立于已有工作的技术创新及其有效性证据；完整文稿不代表已经达到录用标准。继续盲目增加训练轮次，不能补上创新缺口。'),heading('作者、时间与剩余事项'),text('作者顺序按用户提供记录：朱棣、赵耀，均为复旦大学；英文拼写暂为 Di Zhu、Yao Zhao，待作者确认。其他作者与通讯作者待定。摘要尚未登记：截止北京时间 2026-10-29 19:59；全文截止 2026-11-05 19:59。应尽快完成作者信息、摘要登记决定和投稿定位，最终上传前再次核对会议要求。'),text('尚需作者科学审阅、确认创新定位、核查正式姓名/通讯作者、准备合规的公共代码归档链接并完成最终提交检查。尚未实际提交，也未公开发布代码或向他人发送材料。更接近的 genome-scale 原代 T 数据 Zenodo 18876252 处于禁运状态，未使用其标签。'),heading('文件保护与资源'),text('所有新增文件仍限于 day25_26。原大纲、工作计划、用户添加文件、Digital_Organ_Twin 和旧投稿基线保持原位；98 项原文件逐一核查哈希。没有使用云端或购买资源，目录总逻辑占用仍低于 100 GB。验证和稿件更新完成后暂停本条监控。'))]

def update_manifest(manifest,paper):
 manifest.update(state='external_validation_and_manuscript_updated',main_pages=next(i for i,pg in enumerate(paper) if pg[0].get('text')=='References'),references=10,appendices=3,completed_external_studies=['Replogle2022 K562/RPE1','Arce2025 GSE278572 primary-T CRISPRi'],additional_primary_T_study='complete; all four backgrounds and three source seeds reported; not donor/laboratory-disjoint validation')
 for p in [R/'results/summary.json',R/'results/coverage.json',R/'results/postrun_audit.json',R/'results/paired_target_contrasts.json',R/'protocol_frozen.json',R/'prepared/count_provenance.json']:
  manifest['sources'][p.relative_to(B).as_posix()]=hashlib.sha256(p.read_bytes()).hexdigest()
 return manifest
